#requires -version 5.1
$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));Set-Location $root
Import-Module (Join-Path $root 'app\MemoryClear.Tasks.psm1')
$module=Get-Module MemoryClear.Tasks
Add-Type -TypeDefinition 'using System;using System.Threading;using System.Collections.Concurrent;public static class QaWaitCancel {public static Thread Start(ConcurrentQueue<object> events,CancellationTokenSource token){var t=new Thread(()=>{var end=DateTime.UtcNow.AddSeconds(20);while(events.IsEmpty&&DateTime.UtcNow<end&&!token.IsCancellationRequested)Thread.Sleep(10);if(!events.IsEmpty)token.Cancel();});t.IsBackground=true;t.Start();return t;}}'
$fixtureRoot=Join-Path $root ('artifacts\task-fixture-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $fixtureRoot|Out-Null
$exe=Join-Path $fixtureRoot 'MemoryClear.TaskQA.exe'
$source='using System;using System.Windows.Forms; public class QForm:Form {protected override bool ShowWithoutActivation {get{return true;}} protected override CreateParams CreateParams {get{var p=base.CreateParams;p.ExStyle|=0x08000000;return p;}}} public class QA { [STAThread] public static void Main(string[] args){var f=new QForm{Text="MemoryClear disposable QA",ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,Location=new System.Drawing.Point(-32000,-32000)};if(args.Length>0&&args[0]=="hold")f.FormClosing+=(s,e)=>e.Cancel=true;Application.Run(f);}}'
Add-Type -TypeDefinition $source -ReferencedAssemblies System.Windows.Forms,System.Drawing -OutputAssembly $exe -OutputType WindowsApplication
$results=New-Object 'System.Collections.Generic.List[object]';$children=New-Object 'System.Collections.Generic.List[object]'
function Assert {param([bool]$Value,[string]$Message='Assertion failed');if(-not$Value){throw $Message}}
function Reject {param([scriptblock]$Action);$failed=$false;try{&$Action|Out-Null}catch{$failed=$true};Assert $failed 'Expected rejection'}
function Check {param([string]$Name,[scriptblock]$Action);try{&$Action;$results.Add([pscustomobject]@{Name=$Name;Passed=$true;Error=''})}catch{$results.Add([pscustomobject]@{Name=$Name;Passed=$false;Error=$_.Exception.Message})}finally{foreach($key in @([MemoryClear.TaskSessionStore]::Plans.Keys)){Close-MCTaskPlan $key}}}
function Child {param([string]$Mode='normal');$p=Start-Process -FilePath $exe -ArgumentList $Mode -WindowStyle Hidden -PassThru;$children.Add($p);for($i=0;$i-lt50;$i++){Start-Sleep -Milliseconds 100;if([MemoryClear.Native]::TaskWindow($p.Id)){break}};$id=[MemoryClear.Native]::Inspect($p.Id);[pscustomobject]@{Process=$p;Row=[pscustomobject]@{Pid=$p.Id;StartTicks=$id.StartTicks;Path=$id.Path;Name='Own QA';RamMB=0}}}
$settings=[pscustomobject]@{SchemaVersion=1;ProtectedPaths=@();AllowClosePaths=@($exe);RefreshSeconds=3;AutoKill=$false}
$policy=Get-MCTaskPolicy;$policy.executionEnabled=$true;$policy.closeTimeoutSeconds=2
# Test-only providers live in this module instance. No user settings or shipped policy file changed.
& $module {param($Settings,$Policy);$script:QaSettings=$Settings;$script:QaPolicy=$Policy;function script:Get-MCSettings {$script:QaSettings};function script:Get-MCTaskPolicy {$script:QaPolicy};function script:Get-MCContext {[pscustomobject]@{UserSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;SessionId=[Diagnostics.Process]::GetCurrentProcess().SessionId;SelfId=$PID;WindowsRoot=[IO.Path]::GetFullPath($env:windir).TrimEnd('\')+'\';Services=@{};ServicesKnown=$true;Source='Test-owned QA child executables, not a production service inventory'}}} $settings $policy
& $module {$script:QaServicesKnown=$true;function script:Get-MCContext {[pscustomobject]@{UserSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;SessionId=[Diagnostics.Process]::GetCurrentProcess().SessionId;SelfId=$PID;WindowsRoot=[IO.Path]::GetFullPath($env:windir).TrimEnd('\')+'\';Services=@{};ServicesKnown=$script:QaServicesKnown;Source='Test-only QA children; synthetic service inventory'}}}
& $module {function script:Get-MCTaskForegroundId {$PID}}
try{
 Check 'Nonempty opt-in binds live PID/start/window/executable fingerprint' {$c=Child;$p=New-MCTaskPlan @($c.Row) -Context 'qa';Assert ($p.EligibleCount-eq1-and$p.Items[0].Executable.Sha256.Length-eq64-and$p.Items[0].Window-ne0) 'No native eligible QA target'}
 Check 'Confirmation and context cannot be bypassed' {$c=Child;$p=New-MCTaskPlan @($c.Row) -Context 'qa';Reject {Invoke-MCTaskPlan $p.Id 'qa'};Reject {Confirm-MCTaskPlan $p.Id 'qa' $false};Reject {Confirm-MCTaskPlan $p.Id 'other' $true};Assert (-not$c.Process.HasExited) 'Unapproved action'}
 Check 'Graceful close verifies exit, journals outcome and cannot replay' {$c=Child;$p=New-MCTaskPlan @($c.Row) -Context 'qa';if($p.EligibleCount-eq0){throw ($p.Items|ConvertTo-Json -Depth 6 -Compress)};Confirm-MCTaskPlan $p.Id 'qa' $true;$r=Invoke-MCTaskPlan $p.Id 'qa';Assert ($r.Status-eq'Completed'-and$r.Exited-eq1-and$c.Process.WaitForExit(1000)) ($r|ConvertTo-Json -Depth 6 -Compress);Assert ([IO.File]::ReadAllText($r.Journal).Contains('Outcome')) 'No evidence';Reject {Invoke-MCTaskPlan $p.Id 'qa'}}
 Check 'Save-prompt refusal stays alive after timeout, zero force' {$c=Child 'hold';$p=New-MCTaskPlan @($c.Row) -Context 'qa';if($p.EligibleCount-eq0){throw ($p.Items|ConvertTo-Json -Depth 6 -Compress)};Confirm-MCTaskPlan $p.Id 'qa' $true;$r=Invoke-MCTaskPlan $p.Id 'qa';Assert ($r.Status-eq'Partial'-and$r.Items[0].Status-eq'HeldTimeout'-and-not$r.Items[0].ForceUsed-and-not$c.Process.HasExited) 'Held app forced'}
 Check 'Cancellation before action preserves QA child' {$c=Child;$p=New-MCTaskPlan @($c.Row) -Context 'qa';Confirm-MCTaskPlan $p.Id 'qa' $true;$token=New-Object Threading.CancellationTokenSource;try{$token.Cancel();$r=Invoke-MCTaskPlan $p.Id 'qa' -CancellationToken $token.Token;Assert ($r.Status-eq'Cancelled'-and$r.Processed-eq0-and-not$c.Process.HasExited)}finally{$token.Dispose()}}
 Check 'Changed opt-in permission invalidates before close' {$c=Child;$p=New-MCTaskPlan @($c.Row) -Context 'qa';Confirm-MCTaskPlan $p.Id 'qa' $true;$settings.AllowClosePaths=@();try{Reject {Invoke-MCTaskPlan $p.Id 'qa'};Assert (-not$c.Process.HasExited)}finally{$settings.AllowClosePaths=@($exe)}}
 Check 'Stale start-time and protected target cannot become eligible' {$c=Child;$c.Row.StartTicks++;$p=New-MCTaskPlan @($c.Row) -Context 'qa';Assert ($p.EligibleCount-eq0);Reject {Confirm-MCTaskPlan $p.Id 'qa' $true};$c=Child;$settings.ProtectedPaths=@($exe);try{$p=New-MCTaskPlan @($c.Row) -Context 'qa';Assert ($p.EligibleCount-eq0)}finally{$settings.ProtectedPaths=@()}}
 Check 'TTL expiry and closed session never execute' {$c=Child;$p=New-MCTaskPlan @($c.Row) -Context 'qa';Confirm-MCTaskPlan $p.Id 'qa' $true;[MemoryClear.TaskSessionStore]::Plans[$p.Id].Expires=[DateTime]::UtcNow.AddSeconds(-1);Reject {Invoke-MCTaskPlan $p.Id 'qa'};Close-MCTaskPlan $p.Id;Reject {Invoke-MCTaskPlan $p.Id 'qa'};Assert (-not$c.Process.HasExited)}
 Check 'Wrong window identity is skipped without force or broadcast' {$c=Child;$p=New-MCTaskPlan @($c.Row) -Context 'qa';Confirm-MCTaskPlan $p.Id 'qa' $true;$s=[MemoryClear.TaskSessionStore]::Plans[$p.Id];$items=$s.Payload|ConvertFrom-Json;$items.Thread=[uint32]1;$s.Payload=$items|ConvertTo-Json -Depth 12 -Compress;$r=Invoke-MCTaskPlan $p.Id 'qa';Assert ($r.Items[0].Status-eq'Skipped'-and-not$c.Process.HasExited)}
 Check 'Fresh missing service inventory preserves already-approved QA child' {$c=Child;$p=New-MCTaskPlan @($c.Row) -Context 'qa';Confirm-MCTaskPlan $p.Id 'qa' $true;&$module {$script:QaServicesKnown=$false};try{$r=Invoke-MCTaskPlan $p.Id 'qa';Assert ($r.Items[0].Status-eq'Skipped'-and-not$c.Process.HasExited)}finally{&$module {$script:QaServicesKnown=$true}}}
 Check 'Changed frozen executable fingerprint cannot close target' {$c=Child;$p=New-MCTaskPlan @($c.Row) -Context 'qa';Confirm-MCTaskPlan $p.Id 'qa' $true;$s=[MemoryClear.TaskSessionStore]::Plans[$p.Id];$items=$s.Payload|ConvertFrom-Json;$items.Executable.Sha256=('0'*64);$s.Payload=$items|ConvertTo-Json -Depth 12 -Compress;$r=Invoke-MCTaskPlan $p.Id 'qa';Assert ($r.Items[0].Status-eq'Skipped'-and$r.Items[0].Reason.Contains('hash')-and-not$c.Process.HasExited)}
 Check 'Cancellation during close wait keeps unresponsive QA child alive' {$c=Child 'hold';$p=New-MCTaskPlan @($c.Row) -Context 'qa';Confirm-MCTaskPlan $p.Id 'qa' $true;$token=New-Object Threading.CancellationTokenSource;$events=New-Object 'Collections.Concurrent.ConcurrentQueue[object]';$watcher=[QaWaitCancel]::Start($events,$token);try{$r=Invoke-MCTaskPlan $p.Id 'qa' -CancellationToken $token.Token -Events $events;Assert ($r.Status-eq'Cancelled'-and$r.Items[0].Status-eq'HeldCancelled'-and-not$r.Items[0].ForceUsed-and-not$c.Process.HasExited) ($r|ConvertTo-Json -Depth 6 -Compress)}finally{$token.Cancel();$watcher.Join(1000)|Out-Null;$token.Dispose()}}
 Check 'Unknown foreground after approval keeps QA child alive' {$c=Child;$p=New-MCTaskPlan @($c.Row) -Context 'qa';Confirm-MCTaskPlan $p.Id 'qa' $true;&$module {function script:Get-MCTaskForegroundId {0}};try{$r=Invoke-MCTaskPlan $p.Id 'qa';Assert ($r.Items[0].Status-eq'Skipped'-and$r.Items[0].Reason.Contains('Foreground')-and-not$c.Process.HasExited)}finally{&$module {function script:Get-MCTaskForegroundId {$PID}}}}
}finally{foreach($p in $children){try{$p.Refresh();if(-not$p.HasExited){$id=[MemoryClear.Native]::Inspect($p.Id);if($id.Path-eq$exe){$p.Kill();$p.WaitForExit(2000)|Out-Null}}}finally{$p.Dispose()}}}
$report=[pscustomobject]@{Timestamp=[DateTime]::UtcNow.ToString('o');Runtime=$PSVersionTable.PSVersion.ToString();Passed=@($results|Where-Object{$_.Passed}).Count;Failed=@($results|Where-Object{-not$_.Passed}).Count;Checks=$results.ToArray();Scope='Only disposable test-owned hidden QA child executables; synthetic foreground/service inventory/opt-in/policy providers isolated to test module; no real app closed/settings modified';Unverified=@('Windows10','Human save-dialog/DPI','Adversarial window races/mapped exe writers','Full historic phase gates/CLI matrix')}
$report|ConvertTo-Json -Depth 7|Set-Content (Join-Path $root 'docs\verification\task-release-tests.json') -Encoding UTF8
Write-Host ('Task release: '+$report.Passed+' passed, '+$report.Failed+' failed');if($report.Failed){$report.Checks|Where-Object{-not$_.Passed}|Format-List;exit 1}
